CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, credits INTEGER NOT NULL DEFAULT 120 CHECK(credits >= 0), plan TEXT NOT NULL DEFAULT 'trial', subscription_status TEXT NOT NULL DEFAULT 'trial', stripe_customer_id TEXT UNIQUE, stripe_subscription_id TEXT UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, resets_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, filename TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL, duration REAL, provenance TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), title TEXT NOT NULL, mode TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', timeline TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, rendered_revision INTEGER, output_asset_id TEXT REFERENCES assets(id), description TEXT NOT NULL DEFAULT '', scheduled_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS characters (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), data TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS presets (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), data TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pipelines (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, config TEXT NOT NULL, interval_hours INTEGER NOT NULL, max_runs INTEGER NOT NULL, budget INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 0, next_run INTEGER NOT NULL, runs INTEGER NOT NULL DEFAULT 0, spent INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), project_id TEXT REFERENCES projects(id), pipeline_id TEXT REFERENCES pipelines(id), kind TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', stage TEXT NOT NULL DEFAULT 'Queued', progress REAL, error TEXT, input TEXT NOT NULL, revision INTEGER NOT NULL, cost INTEGER NOT NULL, idempotency_key TEXT NOT NULL, lease_until INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(workspace_id, idempotency_key));
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(state, created_at);
CREATE TABLE IF NOT EXISTS render_results (job_id TEXT NOT NULL REFERENCES jobs(id), project_id TEXT NOT NULL REFERENCES projects(id), asset_id TEXT NOT NULL REFERENCES assets(id), revision INTEGER NOT NULL, PRIMARY KEY(job_id,project_id));
CREATE INDEX IF NOT EXISTS projects_workspace ON projects(workspace_id, updated_at);
CREATE INDEX IF NOT EXISTS assets_workspace ON assets(workspace_id, created_at);
CREATE TABLE IF NOT EXISTS credit_ledger (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), job_id TEXT REFERENCES jobs(id), operation TEXT NOT NULL, amount INTEGER NOT NULL, detail TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS usage_events (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), job_id TEXT REFERENCES jobs(id), category TEXT NOT NULL, units REAL NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_events (id TEXT PRIMARY KEY, type TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS system_state (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES (1, unixepoch() * 1000);
